import { test, expect } from '@playwright/test';

test.describe('Screen Reader Error Message Announcement', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should announce error messages for invalid email input using screen reader', async ({ page }) => {
    // Setup: intercept the form submission with an invalid email
    await page.route('**/api/form-submit', (route) => {
      route.abort('API call failed');
    });

    // Intercept the API response with error
    await page.route('**/api/form-submit', (route) => {
      route.continue({
        status: 500,
        body: JSON.stringify({ error: 'Invalid email format' })
      });
    });

    // Intercept the API response with success
    await page.route('**/api/form-submit', (route) => {
      route.continue({
        status: 200,
        body: JSON.stringify({ success: true })
      });
    });

    // Setup: intercept the API call
    await page.route('**/api/form-submit', (route) => {
      route.continue({
        status: 200,
        body: JSON.stringify({ success: true })
      });
    });

    // Setup: intercept the API call with error
    await page.route('**/api/form-submit', (route) => {
      route.continue({
        status: 500,
        body: JSON.stringify({ error: 'Invalid email format' })
      });
    });

    // Setup: intercept the API call with success
    await page.route('**/api/form-submit', (route) => {
      route.continue({
        status: 200,
        body: JSON.stringify({ success: true })
      });
    });

    // Fill in the email field with invalid value
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('invalid-email');

    // Fill in the password field
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('password123');

    // Click the submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message is announced by screen reader
    const errorMessage = page.getByText('Invalid email format');
    await expect(errorMessage).toBeVisible();

    // Verify error message is announced by screen reader
    await expect(page).toHaveRole('alert');

    // Verify success message is not announced
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).not.toBeVisible();
  });

  test('should announce error messages for empty required fields using screen reader', async ({ page }) => {
    // Setup: intercept the form submission with success
    await page.route('**/api/form-submit', (route) => {
      route.continue({
        status: 200,
        body: JSON.stringify({ success: true })
      });
    });

    // Fill in the email field with empty value
    const emailInput = page.getByLabel('Email');
    await emailInput.fill('');

    // Fill in the password field
    const passwordInput = page.getByLabel('Password');
    await passwordInput.fill('password123');

    // Click the submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify error message is announced by screen reader
    const errorMessage = page.getByText('Email is required');
    await expect(errorMessage).toBeVisible();

    // Verify error message is announced by screen reader
    await expect(page).toHaveRole('alert');

    // Verify success message is not announced
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).not.toBeVisible();
  });
});
